from pathlib import Path
root=Path(__file__).resolve().parents[1];base=root/'app/src/main/assets/arcade/dash'
lines=['# Dash asset sources — v0.33.0','', 'All gameplay files are local PNGs. No art is hotlinked. Rendering uses cached images and nearest-neighbor pixels.','', '## Downloaded reference / adapted route art','', 'Source: [pret/pokeemerald general tileset](https://github.com/pret/pokeemerald/tree/master/data/tilesets/primary/general). Downloaded `tiles.png`, `metatiles.bin`, and `palettes/00.pal` through `15.pal` on 2026-10-09. Exact downloaded bytes are retained in `scripts/dash-source/`. These are Pokémon Emerald graphics, copyright their respective Nintendo / Game Freak / Creatures owners; the decompilation repository does not confer an independent redistribution license on game artwork. Used for this personal fan project as requested.','', 'Adaptation: assemble metatile 281 for textured sand/path, 1 for verge, 30/31/46/47 for evergreen, 224 for boulder, plus Emerald machine/rail metatiles 305/308/328 for the Electric and Steel course obstacles. Remove matching underlying turf colors; tint selected themes; retain native pixel geometry. Fire course rock art now also derives from the Emerald boulder. Reproduce with `scripts/adapt-emerald-dash-assets.py` after `scripts/build-dash-pixel-assets.py`.','', 'Pokémon actor sprites are unchanged from supplied v0.30.0 in `arcade/sprites/actors/pokemon/` (including shiny variants). [PokeAPI/sprites](https://github.com/PokeAPI/sprites) was investigated as requested; no replacement racer sprites were downloaded. Existing sprite manifests/attribution remain unchanged.','', '## Original art','', 'Remaining tiles, irregular edge transitions, themed objects, double-chevron boost pads, props, pixel shadow/ring/cursor and finish strip are original programmatically authored pixel art, generated by `scripts/build-dash-pixel-assets.py`. Dash stamina pickups now reuse the already-packaged PokeAPI Oran Berry item sprite (`arcade/sprites/items/oran-berry.png`) instead of the former generated pickup art. New original artwork may be reused under CC0; that grant excludes all adapted Pokémon Emerald graphics and existing Pokémon/PokeAPI sprites.','', 'Theme direction: meadow, volcanic ash, coastal boardwalk, power station, woodland, ice, training pass, toxic marsh, desert, highland, crystal route, deep forest, quarry, graveyard, summit, moonlit forest, rail yard, luminous grove. Object silhouettes differ as well as palettes.','', '## Runtime file inventory','', '| Local path (under app/src/main/assets/) | Source / adaptation | Use |','|---|---|---|']
for p in sorted(base.rglob('*.png')):
 type=p.stem.split('-')[0];name=p.stem[len(type)+1:];kind=p.parent.name
 adapted=(kind=='tiles' and name.startswith('road-') and type not in ['steel','electric','water','fire']) or (kind=='tiles' and name=='verge' and type in ['normal','grass','bug','dark','fairy']) or (kind=='objects' and name=='prop' and type in ['normal','grass','bug','dark','fairy','electric','steel']) or (kind=='objects' and name=='rock' and type in ['normal','water','rock','ground','ice','fire','electric','steel'])
 source='pret/pokeemerald/data/tilesets/primary/general (assembled / tinted)' if adapted else 'Original LuckyDex pixel art'
 if p.stem=='menu-panorama':source='Composite local route assets plus unchanged actor sprites 25/127/113; built by scripts/build-dash-menu-panorama.py'
 if kind=='ui' and name=='scene':source='Composite of that theme’s local assets (adapted and original as listed)'
 lines.append(f'| `{p.relative_to(root/"app/src/main/assets").as_posix()}` | {source} | {kind}: {p.stem} |')
(root/'docs/DASH_ASSET_SOURCES.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Documented all',len(list(base.rglob('*.png'))),'runtime assets and 18 reference inputs')
